// src/components/utils/googleSheetLogger.js

const GSHEETS_API_URL =
  "https://script.google.com/macros/s/AKfycbwi4FJcsRLyzMrveEnOXIvk1sIhVY4ptowNRZzKa5QqDLFjt1MUQ_LBpjBNI9szneqlvg/exec";
const GAS_CALLBACK_NAME = "handleGasResponse";

export function saveToSheet(logData) {
  const callbackName = `handleGasResponse_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const encodedData = encodeURIComponent(JSON.stringify(logData));
  const finalUrl = `${GSHEETS_API_URL}?data=${encodedData}&callback=${callbackName}`;

  return new Promise((resolve) => {
    window[callbackName] = function (responseData) {
      clearTimeout(window[`_gasTimeout_${callbackName}`]);
      const scriptTag = document.getElementById(`gas-script-${callbackName}`);
      if (scriptTag) scriptTag.remove();
      delete window[callbackName];
      resolve(responseData);
    };

    const script = document.createElement("script");
    script.src = finalUrl;
    script.id = `gas-script-${callbackName}`;

    window[`_gasTimeout_${callbackName}`] = setTimeout(() => {
      const scriptTag = document.getElementById(`gas-script-${callbackName}`);
      if (scriptTag) scriptTag.remove();
      delete window[callbackName];
      resolve({ status: "timeout" });
    }, 15000);

    script.onerror = () => {
      clearTimeout(window[`_gasTimeout_${callbackName}`]);
      const scriptTag = document.getElementById(`gas-script-${callbackName}`);
      if (scriptTag) scriptTag.remove();
      delete window[callbackName];
      resolve({ status: "error" });
    };

    document.body.appendChild(script);
  });
}
